<script setup lang="ts">
import{computed,nextTick,onBeforeUnmount,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{AlertTriangle,Clock3,CornerDownLeft,DoorOpen,Settings,Stethoscope}from'@lucide/vue';import{api,apiError}from'@/services/api';import{streamPatientReply}from'@/services/sse';import type{ClinicalSession,SessionTurn}from'@/types';import{useLocaleStore}from'@/stores/locale'
const route=useRoute(),router=useRouter(),locale=useLocaleStore(),session=ref<ClinicalSession|null>(null),input=ref(''),streaming=ref(false),ending=ref(false),error=ref(''),seconds=ref(0),messagesEl=ref<HTMLElement|null>(null),aborter=ref<AbortController|null>(null);let timer:number|undefined
const elapsed=computed(()=>`${String(Math.floor(seconds.value/60)).padStart(2,'0')}:${String(seconds.value%60).padStart(2,'0')}`)
async function scrollBottom(){await nextTick();messagesEl.value?.scrollTo({top:messagesEl.value.scrollHeight,behavior:'smooth'})}
onMounted(async()=>{try{session.value=await api.getSession(String(route.params.sessionId));seconds.value=Math.floor((Date.now()-new Date(session.value.startedAt).getTime())/1000);timer=window.setInterval(()=>seconds.value++,1000);await scrollBottom()}catch(e){error.value=apiError(e)}})
onBeforeUnmount(()=>{if(timer)clearInterval(timer);aborter.value?.abort()})
async function send(){const content=input.value.trim();if(!content||streaming.value||!session.value)return;input.value='';error.value='';const student:SessionTurn={id:`local-s-${Date.now()}`,role:'student',content};const patient:SessionTurn={id:`local-p-${Date.now()}`,role:'patient',content:''};session.value.turns.push(student,patient);streaming.value=true;aborter.value=new AbortController();await scrollBottom();try{for await(const event of await streamPatientReply(session.value.id,content,aborter.value.signal)){if(event.type==='meta'&&event.studentTurnId)student.id=String(event.studentTurnId);if(event.type==='delta')patient.content+=event.delta||'';if(event.turnId)patient.id=event.turnId;if(event.type==='error')throw new Error(event.message);await scrollBottom()}}catch(e){session.value.turns=session.value.turns.filter(t=>t!==student&&t!==patient);error.value=apiError(e,'The patient could not respond. Please ask your question again.')}finally{streaming.value=false;aborter.value=null}}
async function finish(){if(!session.value||streaming.value)return;if(!confirm(locale.t('End this consultation and start generating formative feedback? You cannot add more questions afterwards.')))return;ending.value=true;error.value='';try{const result=await api.completeSession(session.value.id);if(result.status==='completed'&&result.resultId)await router.push(`/student/feedback/${result.resultId}`);else await router.push({path:'/student/history',query:{evaluation:'started',session:session.value.id}})}catch(e){error.value=apiError(e,locale.t('Could not complete the consultation.'))}finally{ending.value=false}}
</script>
<template><div class="consultation"><header class="consultation__header"><div class="consultation__brand"><span class="case-avatar"><Stethoscope :size="19"/></span><div><b>{{session?.caseTitle||locale.t('Clinical consultation')}}</b><small>{{locale.t('AI standardised patient · Formative practice')}}</small></div></div><div class="consultation__tools"><button class="text-button consultation__language" :aria-label="`${locale.t('Settings')}: ${locale.languageLabel}`" @click="locale.toggle()"><Settings :size="15"/>{{locale.languageLabel}}</button><span class="consultation__timer"><Clock3 :size="16"/>{{elapsed}}</span><button class="button button--secondary button--sm" :disabled="ending||streaming" @click="finish"><DoorOpen :size="16"/>{{ending?locale.t('Ending…'):locale.t('End consultation')}}</button></div></header><main ref="messagesEl" class="consultation__messages"><div class="consultation__notice"><AlertTriangle :size="15"/><span><b>{{locale.t('Do not enter real patient information.')}}</b> {{locale.t('This is a synthetic formative simulation, not clinical care. The simulated patient will only share information in response to appropriate questions.')}}</span></div><div v-if="!session&&!error" class="loading"><div class="spinner"></div></div><template v-if="session"><div v-for="turn in session.turns" :key="turn.id" class="message" :class="`message--${turn.role}`"><span class="message__author">{{locale.t(turn.role==='student'?'You':'Patient')}}</span><div class="message__bubble"><span v-if="!turn.content&&streaming" class="typing"><i></i><i></i><i></i></span><template v-else>{{turn.content}}</template></div></div><div v-if="!session.turns.length" class="consultation__prompt"><span>{{locale.t('Begin when you are ready.')}}</span><b>{{locale.t("Introduce yourself and confirm the patient's identity.")}}</b></div></template></main><div class="consultation__composer"><div v-if="error" class="alert alert--error">{{error}}</div><form @submit.prevent="send"><textarea v-model="input" class="textarea" rows="2" :placeholder="locale.t('Ask the simulated patient a history-taking question…')" :aria-label="locale.t('Question for the simulated patient')" :disabled="streaming" @keydown.enter.exact.prevent="send"></textarea><button class="send-button" :disabled="!input.trim()||streaming" :aria-label="locale.t('Send question')"><CornerDownLeft :size="19"/></button></form><small>{{locale.t('Do not include real patient data · Press Enter to send · Shift + Enter for a new line')}}</small></div></div></template>
<style scoped>.consultation{height:100vh;background:#f7faf8;display:grid;grid-template-rows:auto 1fr auto}.consultation__header{background:#fff;border-bottom:1px solid var(--line);padding:13px clamp(17px,4vw,48px);display:flex;align-items:center;justify-content:space-between;gap:20px}.consultation__brand{display:flex;align-items:center;gap:11px}.consultation__brand div{display:grid}.consultation__brand b{font-size:13px}.consultation__brand small{font-size:10px;color:var(--muted)}.case-avatar{width:38px;height:38px;display:grid;place-items:center;color:var(--green);background:var(--green-soft);border-radius:50%}.consultation__tools{display:flex;align-items:center;gap:17px}.consultation__timer{display:flex;gap:6px;align-items:center;font-variant-numeric:tabular-nums;font-size:13px;color:#55645f}.consultation__messages{overflow-y:auto;padding:28px max(20px,calc((100vw - 780px)/2))}.consultation__notice{display:flex;gap:8px;align-items:flex-start;background:#ecf3f0;color:#5a6b65;padding:10px 14px;border-radius:10px;font-size:11px;margin-bottom:25px}.message{display:flex;flex-direction:column;margin:17px 0;max-width:79%}.message--student{margin-left:auto;align-items:flex-end}.message__author{font-size:10px;text-transform:uppercase;letter-spacing:.07em;color:#84908c;margin:0 8px 5px}.message__bubble{background:#fff;border:1px solid var(--line);border-radius:4px 16px 16px 16px;padding:13px 16px;color:#374641;line-height:1.65;font-size:14px;white-space:pre-wrap}.message--student .message__bubble{background:var(--green);color:white;border-color:var(--green);border-radius:16px 4px 16px 16px}.consultation__prompt{text-align:center;display:grid;color:#77847f;gap:5px;padding:70px 15px}.consultation__prompt b{font:600 21px 'Source Serif 4',serif;color:#40504a}.consultation__composer{background:#fff;border-top:1px solid var(--line);padding:13px max(20px,calc((100vw - 780px)/2)) 18px}.consultation__composer form{position:relative}.consultation__composer textarea{padding-right:55px;min-height:61px}.consultation__composer>small{display:block;text-align:right;color:#87938e;font-size:9px}.send-button{position:absolute;right:9px;bottom:9px;width:39px;height:39px;display:grid;place-items:center;border:0;border-radius:9px;background:var(--green);color:white;cursor:pointer}.send-button:disabled{opacity:.4}.typing{display:flex;gap:4px;padding:5px}.typing i{width:6px;height:6px;background:#8ba298;border-radius:50%;animation:bop 1s infinite alternate}.typing i:nth-child(2){animation-delay:.2s}.typing i:nth-child(3){animation-delay:.4s}@keyframes bop{to{transform:translateY(-4px);opacity:.45}}@media(max-width:620px){.consultation__brand small{display:none}.consultation__timer{display:none}.consultation__messages{padding:20px 14px}.message{max-width:90%}.consultation__header{padding:10px 12px}}</style>
